source='''from collections import Counter

def transform(grid):
    """Between consecutive occurrences of the rarer color in rows and columns,
    recolor intervening cells with 3; preserve the marker cells."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=lambda v: (counts[v], v))
    out = [row[:] for row in grid]

    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                if grid[r][c] != marker:
                    out[r][c] = 3

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] != marker:
                    out[r][c] = 3

    return out
'''
